-- Migration: 002_material_issue.sql
-- Creates the material_issue table for tracking cut pieces issued to operations

CREATE TABLE IF NOT EXISTS "material_issue" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "issue_no" varchar(50) NOT NULL,
    "issue_date" date NOT NULL DEFAULT CURRENT_DATE,
    "joborderid" bigint NOT NULL REFERENCES joborderbooking(id),
    "lotno" varchar(50) NOT NULL,
    "processid" bigint NOT NULL,       -- Category (e.g. STITCHING)
    "operation_id" bigint NOT NULL,    -- Specific operation (processmaster.id)
    "rate" numeric(18, 2) NOT NULL DEFAULT 0.00,
    "cut_qty" numeric(18, 2) NOT NULL,
    "issued_qty" numeric(18, 2) NOT NULL,
    "remark" varchar(250),
    "enterby" varchar(50),
    "createdon" timestamp DEFAULT CURRENT_TIMESTAMP,
    "alterby" varchar(50),
    "alteredon" timestamp,
    "isdeleted" varchar(10) NOT NULL DEFAULT 'NO'
);

CREATE INDEX IF NOT EXISTS idx_material_issue_lotno ON material_issue(lotno);
CREATE INDEX IF NOT EXISTS idx_material_issue_joborder ON material_issue(joborderid);
CREATE INDEX IF NOT EXISTS idx_material_issue_issueno ON material_issue(issue_no);
